css:
p {
  margin: 0;
}

.questionLink {
  width: 100%;
  height: auto;
  font-size: min(16px, 3vw);
}

.questionLink .head .head__text {
  font-size: 1.2em;
  text-align: center;
  font-weight: bold;
}

.questionLink .image,
.questionLink .link {
  margin-top: 1em;
  width: 100%;
}

.questionLink .image img,
.questionLink .image video {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.questionLink .image *+* {
  margin-top: 1em !important;
}

.questionLink .link .link__button {
  width: 100%;
  height: auto;
  display: block;
  background: #EC5B38;
  border-radius: 10px;
  padding: 0.8em 0.5em;
  border-bottom: 6px solid #b63a1b;
  box-sizing: border-box;
  color: #fff;
  text-decoration: none;
  text-align: center;
  font-size: 1.2em;
  font-weight: bold;
}

.questionLink .link .link__button .sub {
  color: #ecc238;
  font-size: 0.8em;
  display: block;
}

.footer {
  margin-top: 3em;
  padding-top: 1em;
  border-top: 2px solid #ccc;
}

.footer__logo {
  width: 20%;
  height: auto;
}

.footer__logo img {
  width: 100%;
  height: auto;
}

.footer__list {
  margin-top: 1em;
  padding-left: 0;
  width: 90%;
  height: auto;
  margin: 1em auto 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  list-style: none;
}

.footer__list li {
  width: 30%;
  height: auto;
  font-size: 0.85em;
}

.footer__list li:before {
  content: '>';
  padding-right: 0.5em;
}

.footer__list li a {
  font-size: 1em;
  color: #7692FF;
}

.footer .copyright {
  background: #A8A492;
  width: 100%;
  height: auto;
  padding: 0.5em 0;
  margin-top: 1em;
}

.footer .copyright .copyright__text {
  font-size: 0.8em;
  color: #fff;
  text-align: center;
  margin: 0;
}

@media screen and (max-width: 600px) {
  .questionLink .footer__list {
    flex-direction: column;
    width: 70%;
  }

  .questionLink .footer__list li+li {
    margin-top: 0.5em;
  }
}

 .mv-bg {
  background-image: url(/uploads/c2b7b0b0bd4d64a304ba935762f6959fdea2fa2d80d65478a97db644de7bea83.jpg);
  background-color: transparent;
  background-size: contain;
  background-position: center bottom;
  background-repeat: no-repeat;
  width: 100%;
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
}

 .mv-content {
  width: 90%;
  max-width: 800px;
  margin: 0 auto;
  display: grid;
  align-items: center;
  grid-template-columns: 300px auto;
  grid-template-areas: "text image" "btn-box image";
}

@media screen and (max-width: 599px) {
   .mv-content {
    grid-template-columns: auto;
    grid-template-areas: "text" "image" "btn-box";
  }
}

 .text {
  grid-area: text;
  padding: 20px;
  box-sizing: border-box;
}

 .text p {
  margin: 0;
}

 .text .main {
  font-size: 24px;
  font-weight: bold;
  line-height: 1.4;
}

 .text .sub {
  font-size: 16px;
  color: #666;
  margin-top: 16px;
  line-height: 1.5;
}

 .image {
  width: 100%;
  grid-area: image;
}

 .image img,
 .image video {
  width: 100%;
  max-width: 100%;
  height: auto;
}

 .btn-box {
  width: 100%;
  grid-area: btn-box;
  padding: 20px;
  box-sizing: border-box;
}

 .link-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 10px 0;
  padding: 10px 20px;
  border-radius: 4px;
  font-size: 16px;
  text-align: center;
  font-weight: bold;
  text-decoration: none !important;
  color: #fff;
  background-color: #000;
  box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;
  box-sizing: border-box;
  transition: opacity 0.3s ease;
}

 .link-btn.black {
  background-color: #000;
  color: #fff;
}

 .link-btn.white {
  background-color: #fff;
  color: #000;
}

 .link-btn .icon {
  display: inline-flex;
  margin-left: 8px;
}

 .link-btn .icon img,
 .link-btn .icon svg {
  width: auto;
  height: 1.5em !important;
}

 .link-btn:hover {
  opacity: 0.8;
}

 .widget-container {
  font-size: clamp(14px, calc(0.63vw + 12px), 16px);
  font-family: serif;
  width: min(1000px, 100%);
  margin-inline: auto;
  box-sizing: border-box;
  color: #1a1a1a;
}

 .widget-container * {
  box-sizing: border-box;
}

 .strengths {
  width: 100%;
  container-type: inline-size;
}

 .strengths-list {
  display: flex;
  flex-direction: column;
  gap: 2.5em;
}

 .strengths-item {
  display: flex;
  align-items: center;
  gap: 2.4em;
}

 .strengths-item:nth-child(even) {
  flex-direction: row-reverse;
}

 .strengths-item .image img {
  display: block;
  width: 100%;
  height: auto;
}

 .strengths-item .number {
  display: block;
  font-size: 2.4em;
  font-weight: 600;
  line-height: 1;
  color: #007deb;
  letter-spacing: 0.02em;
  margin-bottom: 0.3em;
}

 .strengths-item .title {
  display: block;
  font-size: 1.4em;
  font-weight: 600;
  line-height: 1.35;
  color: #1a1a1a;
  margin-bottom: 0.6em;
}

 .strengths-item .desc {
  display: block;
  font-size: 0.875em;
  color: #4a4a4a;
}

@media (max-width: 749px) {
   .strengths-item {
    flex-direction: column-reverse !important;
    gap: 1em;
  }
}

 .widget-container {
  font-size: 16px;
  font-family: serif;
}

 .widget-container * {
  box-sizing: border-box;
  margin-block: -0.175em;
}

 .switch-slide {
  container-type: inline-size;
  background-color: var(--bgColor, #eee);
  transition: background-color 0.5s ease-in-out;
}

 .switch-slide-content {
  width: min(100%, 1200px);
  margin-inline: auto;
  padding: 3em 1em;
}

 .switch-slide-title {
      font-size: 1.35em;
}

 .switch-slide-grid {
  display: grid;
  grid-template-columns: 56% 40%;
  margin-top: 2em;
  gap: 4%;
}

 .switch-slide-frame {
  position: relative;
  left: -10px;
}

 .switch-slide-frame .switch-image {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
  translate: 15px 15px;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
  transition: translate 0.5s ease-in-out, opacity 0.5s ease-in-out;
}

 .switch-slide-frame .switch-image.is-active {
  position: relative;
  z-index: 2;
  top: 0;
  left: 0;
  translate: 0 0;
}

 .switch-slide-frame .switch-image.is-switching {
  translate: 15px 15px;
  opacity: 0;
  transition: translate 0.5s ease-in-out, opacity 0.5s ease-in-out;
}

 .switch-slide-frame .switch-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

 .switch-slide-frame .switch-indicator {
  display: flex;
  align-items: center;
  gap: 15px;
  position: absolute;
  bottom: 5%;
  left: 5%;
  z-index: 100;
}

 .switch-slide-frame .switch-indicator-item {
  font-size: 0.875em;
  line-height: 1;
  width: 16px;
  height: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
}

 .switch-slide-frame .switch-indicator-item.is-active {
  width: 20px;
  height: 20px;
  border: 1px solid #000;
  font-size: 1.1em;
  font-weight: 600;
  padding: 12px;
}

 .switch-slide-frame .switch-indicator-separator {
  width: 50%;
  height: 1px;
  flex-shrink: 0;
  position: relative;
  background-color: rgba(0, 0, 0, 0.2);
}

 .switch-slide-frame .switch-indicator-separator span {
  width: 0%;
  height: 100%;
  background-color: #000;
  margin-block: 0;
  display: block;
}

 .switch-slide-frame .switch-indicator-separator.is-animating span {
  width: 100%;
}

 .switch-slide-info>*+* {
  margin-top: 1em;
}

 .switch-slide-info .title {
  font-size: 1.25em;
}

 img {
  width: 100%;
  height: auto;
}

.reviewTable__area {
  width: 100%;
  height: auto;
  font-size: min(3vw, 16px);
  color: #333;
  background-color: #fafafa;
  padding-bottom: 2em;
}

@media screen and (max-width: 600px) {
  .reviewTable__area {
    background-color: inherit;
  }
}

.reviewTable__area,
.reviewTable__area * {
  box-sizing: border-box;
}

.reviewTable__area img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.reviewTable__area p {
  margin: 0;
}

.reviewTable__area ul,
.reviewTable__area dl,
.reviewTable__area dt,
.reviewTable__area dd {
  padding: 0;
  margin: 0;
  list-style: none;
}

.reviewTable__area .head {
  font-size: 1.5em;
  font-weight: bold;
  color: #666;
  padding-bottom: 0.3em;
  border-bottom: 5px solid #ccc;
}

.reviewTable__area .starWrap {
  margin-top: 0.2em;
  display: flex;
}

.reviewTable__area .starIcon {
  position: relative;
  display: inline-block;
  line-height: 1;
}

.reviewTable__area .starBg {
  color: #FAB12F;
  font-size: 1.22em;
  line-height: 0.61;
}

.reviewTable__area .starFill {
  color: #FAB12F;
  position: absolute;
  top: 0;
  left: 0;
  white-space: nowrap;
  overflow: hidden;
}

.reviewTable__area .btn {
  width: 45%;
  height: auto;
  color: #fff;
  font-size: 1.3em;
  border-radius: 2px;
  text-decoration: none;
  text-align: center;
  padding: 0.5em 0.8em;
  transition: box-shadow 0.2s, top 0.2s;
  position: relative;
  top: 0;
}

.reviewTable__area .btn:hover {
  box-shadow: none;
  transition: box-shadow 0.2s, top 0.2s;
  position: relative;
  top: 3px;
}

.reviewTable__area .linkBtn {
  background: #8AA624;
  box-shadow: 0 3px 0 #607419;
}

.reviewTable__area .grayBtn {
  background: #666;
  box-shadow: 0 3px 0 #333;
}

.reviewTable__box--head {
  width: 100%;
  height: auto;
  padding: 1em;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  column-gap: 5%;
}

.reviewTable__box--head .reviewTable__headBox--ranking {
  width: 20%;
  height: auto;
  background-image: url(/uploads/b2a43120a9b3ac8e0801d4e9ae6c5efa881a7761649f09dc97fdcfb7457d78f1.png);
  background-repeat: no-repeat;
  background-size: contain;
  aspect-ratio: 800/533;
  position: relative;
}

.reviewTable__box--head .reviewTable__headBox--ranking .ranking {
  color: #fff;
  font-size: 2em;
  font-family: serif;
  font-weight: bold;
  position: absolute;
  top: 45%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.reviewTable__headBox--name .name {
  font-size: 1.8em;
  font-weight: bold;
}

.reviewTable__headBox--name .starIcon {
  font-size: 1.5em;
}

.reviewTable__box--head .starWrap .starText {
  font-size: 1em;
  margin-left: 0.5em;
}

.reviewTable__box--main {
  width: 100%;
  height: auto;
  margin-top: 1em;
  padding: 0 1em;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  flex-wrap: wrap;
  column-gap: 5%;
}

@media screen and (max-width: 600px) {
  .reviewTable__box--main {
    flex-direction: column;
    align-items: center;
  }
}

.reviewTable__mainBox--img {
  width: 30%;
  height: auto;
  overflow: hidden;
}

@media screen and (max-width: 600px) {
  .reviewTable__mainBox--img {
    width: 70%;
    order: 1;
  }
}

.reviewTable__mainBox--img a {
  display: block;
  position: relative;
}

.reviewTable__mainBox--img a img {
  transform: scale(1);
  transition: transform 0.4s;
}

.reviewTable__mainBox--img a:hover img {
  transform: scale(1.4);
  transition: transform 0.4s;
  transform-origin: center;
}

.reviewTable__mainBox--img a:after {
  content: '';
  width: 100%;
  height: 100%;
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  background: rgba(0, 0, 0, 0);
  transition: background 0.4s;
}

.reviewTable__mainBox--img a:hover:after {
  background: rgba(0, 0, 0, 0.4);
  transition: background 0.4s;
}

.reviewTable__mainBox--contents {
  width: 65%;
}

@media screen and (max-width: 600px) {
  .reviewTable__mainBox--contents {
    width: 100%;
    margin-top: 2em;
    order: 3;
  }
}

.reviewTable__mainBox--introduct .introductLists li {
  font-size: 0.9em;
}

.reviewTable__mainBox--introduct .introductLists li+li {
  margin-top: 1em;
}

@media screen and (max-width: 600px) {
  .reviewTable__mainBox--introduct {
    border: 2px solid #ccc;
    border-radius: 3px;
    padding: 1em 0.5em 0.5em;
    position: relative;
  }

  .reviewTable__mainBox--introduct .introductHead {
    position: absolute;
    top: -1em;
    left: 1em;
    background-color: #fff;
    padding: 0 0.5em;
    font-weight: bold;
    font-size: 1.2em;
  }
}

.reviewTable__mainBox--price {
  width: 100%;
  margin-top: 1.5em;
}

.reviewTable__mainBox--price .priceLists {
  display: flex;
  justify-content: flex-start;
  align-items: flex-end;
  flex-wrap: wrap;
  border-top: 1px solid #ccc;
}

.reviewTable__mainBox--price .priceLists dt {
  width: 50%;
  border-bottom: 1px solid #ccc;
  font-size: 0.8em;
  padding: 1em 0;
}

.reviewTable__mainBox--price .priceLists dd {
  width: 50%;
  border-bottom: 1px solid #ccc;
  padding: 0 0 0.4em;
}

.reviewTable__mainBox--price .priceLists dd ._bold {
  font-size: 1.4em;
}

.reviewTable__mainBox--campaign {
  width: 100%;
  margin-top: 3em;
}

.reviewTable__mainBox--campaign .text {
  text-align: center;
  font-size: 1.1em;
}

.reviewTable__mainBox--campaign .linkBtn {
  margin: 1em auto 0;
  display: block;
  width: 50%;
}

.reviewTable__mainBox--detail {
  width: 100%;
  margin-top: 1.5em;
}

@media screen and (max-width: 600px) {
  .reviewTable__mainBox--detail {
    order: 2;
  }
}

.reviewTable__mainBox--detail .detailLists {
  display: flex;
  justify-content: flex-start;
  flex-wrap: wrap;
  border-top: 1px solid #ccc;
  border-left: 1px solid #ccc;
}

.reviewTable__mainBox--detail .detailLists dt,
.reviewTable__mainBox--detail .detailLists dd {
  width: 25%;
  height: auto;
  padding: 0.8em 0.5em;
  border-bottom: 1px solid #ccc;
  border-right: 1px solid #ccc;
  display: flex;
  align-items: center;
}

.reviewTable__mainBox--detail .detailLists dt {
  font-weight: bold;
}

.reviewTable__mainBox--detail .detailLists dd {
  background-color: #fff;
}

@media screen and (max-width: 600px) {
  .reviewTable__mainBox--detail .detailLists {
    border-left: none;
  }

  .reviewTable__mainBox--detail .detailLists dt,
  .reviewTable__mainBox--detail .detailLists dd {
    width: 50%;
    border-right: none;
    padding: 0.8em 0;
  }

  .reviewTable__mainBox--detail .detailLists dt {
    font-weight: normal;
  }

  .reviewTable__mainBox--detail .detailLists dd {
    font-size: 1.2em;
  }

  .reviewTable__mainBox--detail .detailLists dd ._large {
    font-size: 1.2em;
    font-weight: bold;
  }

  .reviewTable__mainBox--detail .detailLists dd ._bold {
    font-size: 1.6em;
  }
}

.reviewTable__mainBox--point {
  width: 100%;
  margin-top: 2em;
}

@media screen and (max-width: 600px) {
  .reviewTable__mainBox--point {
    order: 4;
  }
}

.reviewTable__mainBox--point .pointLists {
  margin-top: 1em;
}

.reviewTable__mainBox--point .pointLists li {
  padding-left: 1.3em;
  position: relative;
  font-weight: bold;
}

.reviewTable__mainBox--point .pointLists li::before {
  content: '';
  width: 1em;
  height: 1em;
  display: block;
  position: absolute;
  top: 0.4em;
  left: 0;
  background-image: url(/uploads/c30362c15970e812c6f96c37341f407c35b84a7db0de01b20f8b066632afb84e.png);
  background-repeat: no-repeat;
  background-size: 1em;
}

.reviewTable__mainBox--point .pointLists li .small {
  display: block;
}

.reviewTable__mainBox--point .pointLists li+li {
  margin-top: 0.5em;
}

.reviewTable__reviewBox {
  width: 100%;
  margin-top: 2em;
  padding: 0 1em;
}

.reviewTable__reviewBox .reviewTable__reviewBox--item {
  margin-top: 1em;
  border-bottom: 1px solid #ccc;
}

@media screen and (max-width: 600px) {
  .reviewTable__reviewBox .reviewTable__reviewBox--item {
    font-size: 1.2em;
  }
}

.reviewTable__reviewBox .reviewTable__reviewBox--detail {
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
}

.reviewTable__reviewBox .reviewTable__reviewBox--detail .text {
  margin-left: 1em;
}

.reviewTable__reviewBox .reviewTable__reviewBox--comment {
  margin-top: 0.5em;
}

.reviewTable__reviewBox .reviewTable__reviewBox--comment p+p {
  margin-top: 1em;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful {
  margin: 2em 0 1em;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful .useful {
  color: #666;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful .useful .num {
  color: #DD0303;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful .usefulBtn {
  border: none;
  background-color: transparent;
  font-size: 1em;
  padding-left: 1.2em;
  margin-top: 1em;
  position: relative;
  cursor: pointer;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful .usefulBtn:before {
  content: '';
  width: 1em;
  height: 1em;
  display: block;
  position: absolute;
  top: 0.4em;
  left: 0;
  background-image: url(/uploads/c30362c15970e812c6f96c37341f407c35b84a7db0de01b20f8b066632afb84e.png);
  background-repeat: no-repeat;
  background-size: 1em;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful .usefulBtn:hover {
  color: #9b0000;
}

.reviewTable__reviewBox .reviewTable__reviewBox--useful .usefulBtn:hover:before {
  background-image: url(/uploads/885c046a144ef059f89715ea8b32501a3eff330483049db693250506168eda39.png);
}

.reviewTable__reviewBox--link {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  column-gap: 0.5em;
  margin-top: 2em;
}

.reviewTable__reviewBox--link .text {
  font-size: 1.5em;
  margin-bottom: 0.5em;
}

@media screen and (max-width: 600px) {
  .reviewTable__reviewBox--link {
    flex-wrap: wrap;
  }

  .reviewTable__reviewBox--link .btn {
    width: 100%;
    font-size: 1.5em;
    padding: 0.8em 0;
    border-radius: 5px;
  }

  .reviewTable__reviewBox--link .btn+.btn {
    margin-top: 1em;
  }
}

@media screen and (min-width: 601px) {
  .is-pcHidden {
    display: none !important;
  }
}

@media screen and (max-width: 600px) {
  .is-spHidden {
    display: none !important;
  }
}

._small {
  font-size: 10px;
  font-weight: normal;
}

._bold {
  font-weight: bold;
}

._colorRed {
  color: #DD0303;
}

._underYellow {
  background-image: linear-gradient(to bottom, transparent 0%, transparent 70%, #face2f 71%);
}

._throuth {
  text-decoration: line-through;
}

 .sec-slider-modal {
  padding: 20px 0 40px;
}

 .sec-slider-modal figure,
 .sec-slider-modal img,
 .sec-slider-modal video {
  width: 100%;
  max-width: 100%;
  margin: 0;
  vertical-align: bottom;
}

 .sec-slider-modal .inner {
  max-width: 1100px;
  box-sizing: border-box;
  width: 90%;
  margin: 0 auto;
}

 .sec-slider-modal .title {
  font-size: 24px;
  line-height: 1.8em;
  margin: 0 auto 30px;
  font-weight: bold;
  text-align: center;
  color: #EB6B4F;
}

 .sec-slider-modal .title span {
  border-bottom: solid 2px #EB6B4F;
}

 .sec-slider-modal .lead {
  font-size: 19px;
  color: #000;
  line-height: 1.6em;
  text-align: center;
  font-weight: bold;
  margin: 0;
}

 .sec-slider-modal .note {
  font-size: 10px;
  color: #000;
  text-align: center;
  line-height: 1.8;
  margin: 10px 0 0;
}

 .sec-slider-modal .icon-search {
  position: relative;
}

 .sec-slider-modal .icon-search::before {
  content: "";
  width: 24px;
  height: 24px;
  position: absolute;
  border: 2px solid #EB6B4F;
  border-radius: 50%;
  bottom: 5px;
  right: 5px;
