 .product__info .swiper {
   width: 100%;
   margin-left: -15px;
   margin-right: auto;
   position: relative;
   overflow: hidden;
   list-style: none;
   padding: 0 15px;
   z-index: 1;
   display: block;
 }

 .product__info .swiper-wrapper {
   width: 100%;
   height: 100%;
   z-index: 1;
   display: flex;
   transition-property: transform;
   transition-timing-function: var(--swiper-wrapper-transition-timing-function, initial);
   box-sizing: content-box;
 }

 .product__info .swiper-slide {
   box-sizing: border-box;
   transform: translateZ(0);
   backface-visibility: hidden;
   flex-shrink: 0;
   width: 100%;
   height: 100%;
   position: relative;
   transition-property: transform;
 }

 .product__info .swiper-pagination {
   position: relative;
   text-align: center;
   transition: 0.3s opacity;
   transform: translate3d(0, 0, 0);
   z-index: 10;
   display: flex;
   gap: 0.5em;
   justify-content: center;
   align-items: center;
 }

 .product__info .swiper-pagination-bullet {
   width: 0.75em;
   aspect-ratio: 1/1;
   background-color: #000;
   border-radius: 50%;
   cursor: pointer;
 }

 .product__info .swiper-button-prev,
 .product__info .swiper-button-next {
   position: absolute;
   width: 30px;
   aspect-ratio: 1/1;
   top: calc(50% - 7.5px);
   background-color: #000;
   border-radius: 50%;
   cursor: pointer;
   display: grid;
   place-items: center;
 }

 .product__info .swiper-button-prev::before,
 .product__info .swiper-button-next::before {
   content: "";
   position: relative;
   display: block;
   width: 5px;
   aspect-ratio: 1/1;
   border-top: solid 3px #fff;
 }

 .product__info .swiper-button-prev {
   left: 0;
 }

 .product__info .swiper-button-prev::before {
   left: 1px;
   border-left: solid 3px #fff;
   rotate: -45deg;
 }

 .product__info .swiper-button-next {
   right: 0;
 }

 .product__info .swiper-button-next::before {
   right: 1px;
   border-right: solid 3px #fff;
   rotate: 45deg;
 }


